MOD = 998244353

def is_chaotic(z):
    for i in range(1, len(z)):
        if z[i] == z[i - 1]:
            return False
    return True

def generate_merging_sequences(x, y):
    from itertools import permutations
    n = len(x)
    m = len(y)
    sequences = []
    for perm in permutations([0] * n + [1] * m):
        z = []
        x_iter = iter(x)
        y_iter = iter(y)
        for p in perm:
            if p == 0:
                z.append(next(x_iter))
            else:
                z.append(next(y_iter))
        if is_chaotic(z):
            sequences.append(z)
    return sequences

def f(l1, r1, l2, r2):
    x_sub = x[l1 - 1:r1]
    y_sub = y[l2 - 1:r2]
    sequences = generate_merging_sequences(x_sub, y_sub)
    return len(sequences)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    x = data[0]
    y = data[1]

    n = len(x)
    m = len(y)
    result = 0

    for l1 in range(n):
        for r1 in range(l1, n):
            for l2 in range(m):
                for r2 in range(l2, m):
                    result = (result + f(l1 + 1, r1 + 1, l2 + 1, r2 + 1)) % MOD

    print(result)

if __name__ == "__main__":
    main()
